def cari_biner(nums, target):
    kiri, kanan = 0, len(nums) - 1
    while kiri <= kanan:
        tengah = (kiri + kanan) // 2
        if nums[tengah] == target:
            return tengah
        if nums[tengah] < target:
            kiri = tengah + 1
        else:
            kanan = tengah - 1
    return -1
